BEGIN;
CREATE TABLE IF NOT EXISTS public.catalog(key text PRIMARY KEY,data jsonb);
TRUNCATE public.catalog;
INSERT INTO public.catalog VALUES ('chance_extra',$cat$["Whose desk is this? It was mine.", "I came back for a mug. Just a mug.", "Tell Hal I said hi. Don't tell him I was here.", "My parking spot is still my parking spot. Nobody reassigned it.", "Nobody took me off the fire drill list. Technically I'm a warden.", "They redid the org chart. I'm still on it. Dotted line.", "The rooftop lounge was my idea. Look at it. Look at the state of it.", "That's my stapler. It has my initials on the bottom. Check.", "I'm in the group photo. Back row. Nobody's cropped me out yet.", "I don't work here. I'm just extremely familiar with it.", "Left a Merican in the cooler in 2023. Somebody drank it. I know who.", "The plant by the window is mine. I water it on Thursdays.", "Si Senor. I used to say that. Nobody's picked it up.", "Good morning, Sunshine. Not you. I wasn't talking to you.", "I've been on the email chain this whole time. Every one of them.", "Somebody has to know where the good chair goes at night. I know.", "They gave my desk away. It's fine. I've seen who to.", "I still get the newsletter. I read the whole thing.", "Still not on the payroll. Still here.", "Nobody deactivated my badge. Three years.", "I'm not on the payroll. I'm on the floor. Different things.", "Somebody moved my mug. Three years and somebody moved my mug.", "Fired guy. That's what I call you. That's the whole joke.", "I quit in March. I've quit twice since. It didn't take.", "HR has a file on me. One page. It says quit. That's it.", "I quit.", "Ask Hal. Go on. Ask Hal if I quit."]$cat$::jsonb);
INSERT INTO public.catalog VALUES ('costumes',$cat$[{"id": "cone", "cost": 0.012, "kind": "hat", "mins": 45, "name": "Traffic Cone", "note": "Placed. Not explained."}, {"id": "party", "cost": 0.012, "kind": "hat", "mins": 45, "name": "Party Hat", "note": "It is nobody's birthday."}, {"id": "hardhat", "cost": 0.014, "kind": "hat", "mins": 45, "name": "Hard Hat", "note": "No construction is occurring."}, {"id": "visor", "cost": 0.014, "kind": "hat", "mins": 45, "name": "Accounting Visor", "note": "Green. Translucent. Unearned."}, {"id": "kilt", "cost": 0.02, "kind": "body", "mins": 45, "name": "Business Kilt", "note": "Formal. Ventilated. Non-negotiable."}, {"id": "robe", "cost": 0.018, "kind": "body", "mins": 45, "name": "Bathrobe", "note": "Works from home now, apparently."}, {"id": "hawaii", "cost": 0.016, "kind": "body", "mins": 45, "name": "Hawaiian Shirt", "note": "Mentally on vacation. Physically at the printer."}, {"id": "suit", "cost": 0.022, "kind": "body", "mins": 45, "name": "Interview Suit", "note": "Three pieces. Everyone noticed."}, {"id": "trex", "cost": 0.03, "kind": "body", "mins": 45, "name": "Inflatable T-Rex", "note": "Cannot reach the keyboard. Still on payroll."}, {"id": "mascot", "cost": 0.035, "kind": "body", "mins": 45, "name": "Ledger the Lynx", "note": "The mascot nobody approved."}, {"id": "board", "cost": 0.025, "kind": "body", "mins": 45, "name": "Sandwich Board", "note": "Reads: ASK ME ABOUT SYNERGY."}]$cat$::jsonb);
INSERT INTO public.catalog VALUES ('items',$cat$[{"id": "intern", "cost": 15, "name": "Office Intern", "note": "Helps with tasks and learns the ropes.", "rate": 0.25}, {"id": "poster", "cost": 330, "name": "Motivational Poster", "note": "A kitten hangs from a branch. HR has classified this as a raise.", "rate": 4.12}, {"id": "coffee", "cost": 7260, "name": "Break Room Coffee Machine", "note": "Grinds beans. Grinds people. Mostly people.", "rate": 68}, {"id": "manager", "cost": 160000, "name": "Middle Manager", "note": "Produces nothing measurable. Output rises anyway. Do not investigate.", "rate": 1120}, {"id": "desk", "cost": 3510000, "name": "Standing Desk Initiative", "note": "Nobody stands. Everybody mentions that they could.", "rate": 18500}, {"id": "board", "cost": 77300000, "name": "Synergy Whiteboard", "note": "Covered in arrows. The arrows point at other arrows.", "rate": 306000}, {"id": "openplan", "cost": 1700000000, "name": "Open-Plan Renovation", "note": "Walls removed to encourage collaboration and despair.", "rate": 5040000}, {"id": "allhands", "cost": 37400000000, "name": "Quarterly All-Hands", "note": "Ninety minutes. One slide. Everyone claps at the end, unclear why.", "rate": 83200000}, {"id": "satellite", "cost": 823000000000, "name": "Offshore Satellite Office", "note": "Eleven time zones away. Always somehow already awake.", "rate": 1370000000}, {"id": "bot", "cost": 18100000000000, "name": "Sentient Slack Bot", "note": "Started as a standup reminder. Now approves invoices.", "rate": 22600000000}, {"id": "vending", "cost": 398000000000000, "name": "The Vending Machine That Knows", "note": "It stocks your favorite snack the day before you crave it.", "rate": 373000000000}, {"id": "retreat", "cost": 8760000000000000, "name": "Mandatory Spiritual Retreat", "note": "Trust falls at altitude. Several people come back different.", "rate": 6160000000000}, {"id": "subsidiary", "cost": 193000000000000000, "name": "Wholly Owned Subsidiary", "note": "It has its own Example Property Co. Their leaderboard is worse than ours.", "rate": 102000000000000}, {"id": "holiday", "cost": 4240000000000000000, "name": "Company Holiday Named After You", "note": "Observed regionally. Banks close. Nobody is sure why.", "rate": 1680000000000000}, {"id": "regional", "cost": 93300000000000000000, "name": "Regional Monopoly", "note": "Competitors are referred to internally as \"the others\".", "rate": 27700000000000000}, {"id": "boardseat", "cost": 2050000000000000000000, "name": "A Seat On The Board", "note": "You now sit in the meeting you used to be summoned to.", "rate": 456000000000000000}, {"id": "building", "cost": 45200000000000000000000, "name": "The Building Is Ours", "note": "The landlord works here now. He seems fine about it.", "rate": 7530000000000000000}, {"id": "secondpg", "cost": 994000000000000000000000, "name": "A Second Example Property Co.", "note": "Identical to this one. Slightly better coffee. Do not visit.", "rate": 124000000000000000000}, {"id": "franchise", "cost": 21900000000000000000000000, "name": "A Franchise Model", "note": "Other people run it. You take a percentage. This is the dream, apparently.", "rate": 2730000000000000000000}, {"id": "holding", "cost": 481000000000000000000000000, "name": "A Holding Company", "note": "It owns the other things. Nobody can explain what it does. It does it well.", "rate": 60100000000000000000000}, {"id": "sovereign", "cost": 10600000000000000000000000000, "name": "A Sovereign Wealth Fund", "note": "A small nation now depends on your quarterly numbers. Nobody told them.", "rate": 1320000000000000000000000}, {"id": "annex", "cost": 233000000000000000000000000000, "name": "The Orbital Annex", "note": "Low earth orbit. No commute. Legal has stopped returning calls.", "rate": 29100000000000000000000000}, {"id": "timezone", "cost": 5120000000000000000000000000000, "name": "Your Own Time Zone", "note": "Example Co. Standard Time. Twenty six hours. Nobody has objected loudly enough.", "rate": 640000000000000000000000000}, {"id": "original", "cost": 113000000000000000000000000000000, "name": "The Original Example Property Co.", "note": "It turns out there was one before this one. You have acquired it. Do not ask.", "rate": 14100000000000000000000000000}]$cat$::jsonb);
INSERT INTO public.catalog VALUES ('mail',$cat$[{"w": 18, "id": "payslip", "kind": "pp", "text": "A payslip. The number is correct, which is somehow worse.", "amount": 300}, {"w": 22, "id": "memo", "kind": "none", "text": "An internal memo about memo formatting. It is incorrectly formatted."}, {"w": 16, "id": "snack", "kind": "buff", "mins": 25, "mult": 1.15, "text": "A snack in a plain wrapper. No sender. You eat it immediately."}, {"w": 8, "id": "cheque", "kind": "pp", "text": "An expense reimbursement from a quarter nobody remembers.", "amount": 900}, {"w": 14, "id": "note", "kind": "none", "text": "An anonymous note. It says: I know what you did with the chair."}, {"w": 12, "id": "catalog", "kind": "none", "text": "A catalogue of office furniture. Somebody has circled a chair. Not the good one."}, {"w": 6, "id": "jury", "kind": "none", "text": "Jury duty. Not for you. It is addressed to somebody who left in 2019."}, {"w": 4, "id": "bonus", "kind": "pp", "text": "A discretionary bonus. No explanation. Do not ask Hal.", "amount": 2500}]$cat$::jsonb);
INSERT INTO public.catalog VALUES ('memos_extra',$cat$["The vending machine took a dollar and gave nothing back. It has been noted.", "A meeting invite arrived with no agenda and eleven attendees. Nobody declined.", "The good chair was seen leaving the building. It came back. Nobody asked.", "Someone reheated fish. The investigation is ongoing and will find nothing.", "A single sock has been in the lost and found since 2021. Nobody claims it. Nobody throws it out.", "The office plant was watered twice today by two different people. It is now furious.", "Someone brought in a puzzle. Four hundred pieces. Zero progress. Enormous emotional investment.", "A birthday card is circulating. You are the fourth person to write \"Happy Birthday!\" and nothing else.", "The wifi dropped for nine seconds and productivity has not recovered.", "Somebody labelled their lunch with their full legal name. Things have escalated.", "The thermostat war has entered its fourteenth month. Both sides claim momentum.", "An all-staff email went out with the subject line \"quick one\". It was 900 words.", "Someone said \"let me know if you need anything\" and meant it. The room was unsettled.", "A chair has been rolled from one desk to another overnight. No footage exists.", "The printer printed 47 copies of a blank page. Nobody has admitted to it.", "Somebody scheduled a 4:45pm Friday meeting. They are still employed, for now.", "Somebody has been standing at the mirror for a while now. Everyone is respecting it.", "Four people have walked past the mirror pretending not to look. The mirror knows.", "New badge photo went up. It is a significant improvement and nobody will say so.", "Someone reissued their badge three times in one afternoon. Confidence is a journey.", "A reconciliation from 2023 is sitting half-finished. Nobody will touch it. Nobody will close it.", "Theo has read the contract twice and found the same clause both times. It is still bad.", "Theo says the contract is 'mostly standard'. Theo has never once said fully standard.", "A redline came back with 47 changes. Theo described it as 'a good start'.", "Gus says the project is on schedule. Gus has said this about every project ever.", "A development timeline was revised. The revision moved everything three weeks right.", "Gus walked the site and came back with eleven photos of the same wall.", "Iris has logged a maintenance request that simply says 'noise'. Investigation pending.", "Three rent payments came in early. Iris is suspicious and, historically, correct.", "A tenant called about a smell. Iris has been through this before. Iris has a folder.", "Bramblewick has rebuilt the app again. It is faster. Nobody can point to which part.", "Bramblewick shipped a fix at 11pm and mentioned it casually at 9am like it was nothing.", "The app went down for nine seconds. Bramblewick knows. Bramblewick has always known.", "Somebody asked Hal a question and Hal answered a different, better question.", "Lena listed eleven things before lunch. Nine sold. Two were not hers to list.", "A pallet arrived. Lena already knows what every item on it is worth.", "Somebody offered half asking price. Lena did not reply. They came back at full.", "Lena found a forklift for $1500 and is being very calm about it.", "The resale spreadsheet has a column nobody understands and everyone trusts completely.", "A buyer said 'is this still available' at 6:04am. Lena answered at 6:05.", "Somebody has been in the same meeting for four hours. Nobody has checked on them.", "The good chair was found in an office it does not belong to. No arrests.", "A calendar invite was declined with a note. The note was longer than the invite.", "Someone put 'per my previous message' in writing. The room temperature dropped.", "There is a second fridge. Nobody knows what is in the second fridge.", "The printer worked on the first try. Everyone is unsettled.", "An email chain hit fourteen replies and resolved nothing. It has been archived, not solved.", "Somebody said 'I'll keep it brief' and then did not.", "A meeting ended nine minutes early. Nobody knew what to do with the nine minutes.", "Two people arrived at the coffee machine at once. A silent negotiation took place.", "The office plant has been moved. Nobody moved it. It has been moved.", "Somebody's phone has been buzzing in a drawer since Tuesday.", "A password expired at the worst possible moment, as designed.", "The all-hands slide said 'EXCITING CHANGES'. Everyone read it as a threat.", "Someone has been on mute for the entire call. They looked very engaged.", "A chair was adjusted. The next person adjusted it back. This will continue forever.", "Somebody brought donuts and did not announce it. Four people are still unaware.", "The office thermostat says 71. It has never said anything else.", "Somebody said Good morning Sunshine at 4pm. It was not challenged.", "The margarita machine has been added to a spreadsheet. That is the whole update.", "A Merican was opened at 11am. Nobody has commented. Nobody will.", "The rooftop lounge received a delivery today. The door remains shut.", "Somebody said Si Senor in a client call. The client said it back.", "A meeting was moved to make room for a meeting about the meeting.", "The suggestion box was emptied. Both suggestions were about the box.", "Someone has looked up the office building on Zillow. Twice this week.", "The fire drill went well. Four people did not leave their desks.", "A calendar invite says Hold. It has said Hold for six weeks.", "The good chair has been moved to a different floor entirely. It will find its way back.", "Somebody asked a question for you and then asked it to the room instead.", "A document was shared with edit access. This was almost certainly a mistake.", "The printer produced eleven copies of a page nobody sent.", "Someone brought donuts. There is one left. It has been there since Tuesday.", "The office bingo card has a square that nobody has ever managed to tick.", "An out-of-office reply arrived from somebody sitting nine feet away.", "A recurring meeting was cancelled. The relief was audible and slightly frightening.", "The fridge has been cleaned. Three containers went unclaimed and unmourned.", "Somebody theoretically agreed to something. Theoretically.", "A whiteboard was photographed before being wiped. The photo is blurry.", "The kitchen has run out of the good mugs. There are eleven bad mugs.", "Someone updated their email signature. It is now four lines longer.", "A phone rang in an empty office for a full minute. Nobody moved.", "The thermostat was adjusted by a person who will never admit it.", "Somebody replied all. The thread is now on its fortieth message.", "A laptop has been left open on a spreadsheet. Nobody has looked. Everybody wants to.", "The vending machine has begun stocking something nobody ordered.", "An agenda item says Other. It has been Other for three weeks.", "Somebody laminated something that did not require lamination.", "The parking lot has one space everybody avoids. Nobody remembers why.", "A supplier called asking for a person who has never worked here.", "Somebody has started saying the reality is before every sentence.", "The stapler was returned. No note. No explanation. Slightly warm."]$cat$::jsonb);
INSERT INTO public.catalog VALUES ('office_kit',$cat$[{"id": "d1", "cost": 800000000000000000000000, "name": "A Desk Without A Wobble", "note": "Four legs, all touching the floor. This was not always true.", "secs": 400, "slot": "desk", "tier": 1}, {"id": "d2", "cost": 9600000000000000000000000, "name": "Glass Top", "note": "Shows every fingerprint. Worth it.", "secs": 2400, "slot": "desk", "tier": 2}, {"id": "d3", "cost": 110000000000000000000000000, "name": "Walnut, Or Close Enough", "note": "Veneer. Convincing veneer. Nobody is going to check.", "secs": 14400, "slot": "desk", "tier": 3}, {"id": "d4", "cost": 1400000000000000000000000000, "name": "Actual Marble", "note": "The floor beneath it has been surveyed. It was fine. Probably.", "secs": 86400, "slot": "desk", "tier": 4}, {"id": "d5", "cost": 17000000000000000000000000000, "name": "Something Black And Seamless", "note": "No drawers. No edges. No explanation.", "secs": 518400, "slot": "desk", "tier": 5}, {"id": "c1", "cost": 2000000000000000000000000, "name": "A Chair That Goes Up", "note": "The lever works. It has never worked before.", "secs": 700, "slot": "chair", "tier": 1}, {"id": "c2", "cost": 24000000000000000000000000, "name": "Lumbar Support", "note": "You have opinions about it now. You share them.", "secs": 4900, "slot": "chair", "tier": 2}, {"id": "c3", "cost": 290000000000000000000000000, "name": "The Mesh One From The Catalogue", "note": "The one everybody looked at and nobody ordered.", "secs": 34300, "slot": "chair", "tier": 3}, {"id": "c4", "cost": 3500000000000000000000000000, "name": "Leather. Reclining. Silent.", "note": "It makes no sound at all. This unsettles visitors.", "secs": 240000, "slot": "chair", "tier": 4}, {"id": "r1", "cost": 1500000000000000000000000, "name": "A Rug, Finally", "note": "Covers the stain. Everyone knows about the stain.", "secs": 500, "slot": "rug", "tier": 1}, {"id": "r2", "cost": 18000000000000000000000000, "name": "Something With A Pattern", "note": "Geometric. Inoffensive. Chosen by committee.", "secs": 3500, "slot": "rug", "tier": 2}, {"id": "r3", "cost": 220000000000000000000000000, "name": "A Rug People Comment On", "note": "Two people have asked where it is from. You have not told them.", "secs": 24500, "slot": "rug", "tier": 3}, {"id": "r4", "cost": 2600000000000000000000000000, "name": "Handwoven, Allegedly", "note": "The invoice said handwoven. The invoice said a lot of things.", "secs": 171500, "slot": "rug", "tier": 4}, {"id": "w1", "cost": 3000000000000000000000000, "name": "A Motivational Print", "note": "PERSEVERANCE. A canoe. Nobody has looked at it twice.", "secs": 1200, "slot": "art", "tier": 1}, {"id": "w2", "cost": 36000000000000000000000000, "name": "A Framed Certificate", "note": "Completion, not achievement. The distinction is not visible from the door.", "secs": 8400, "slot": "art", "tier": 2}, {"id": "w3", "cost": 430000000000000000000000000, "name": "An Actual Painting", "note": "Nobody knows who chose it. It has grown on everybody.", "secs": 58800, "slot": "art", "tier": 3}, {"id": "w4", "cost": 5200000000000000000000000000, "name": "The Founder Portrait", "note": "It is not Hal. Nobody will say who it is.", "secs": 411600, "slot": "art", "tier": 4}]$cat$::jsonb);
CREATE OR REPLACE FUNCTION public.ask_raise() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ BEGIN RAISE EXCEPTION 'hal is out of yeses'; END $$;
CREATE TEMP TABLE before_catalog AS SELECT * FROM public.catalog;
CREATE TEMP TABLE before_player AS SELECT to_jsonb(p) AS data FROM public.players p;
\i supabase/migrations/20261021203552_restore_original_names.sql
DO $tests$ BEGIN
 IF EXISTS(SELECT 1 FROM public.catalog WHERE data::text ~ '(Hal|Wes|Bramblewick|Lena|Example Property|rooftop)') THEN RAISE EXCEPTION 'replacement names survived'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.catalog WHERE key='memos_extra' AND data::text LIKE '%Angelica%') THEN RAISE EXCEPTION 'resale name missing'; END IF;
 IF EXISTS(SELECT 1 FROM public.catalog c JOIN before_catalog b USING(key) WHERE jsonb_path_query_array(c.data,'strict $.** ? (@.type() == "number" || @.type() == "boolean")')<>jsonb_path_query_array(b.data,'strict $.** ? (@.type() == "number" || @.type() == "boolean")') OR jsonb_path_query_array(c.data,'strict $.**.id')<>jsonb_path_query_array(b.data,'strict $.**.id')) THEN RAISE EXCEPTION 'catalog economics/IDs changed'; END IF;
 IF EXISTS((SELECT data FROM before_player EXCEPT SELECT to_jsonb(p) FROM public.players p) UNION ALL (SELECT to_jsonb(p) FROM public.players p EXCEPT SELECT data FROM before_player)) THEN RAISE EXCEPTION 'players changed'; END IF;
 IF position('dave is out of yeses' in pg_get_functiondef('public.ask_raise'::regproc))=0 THEN RAISE EXCEPTION 'raise message missing'; END IF;
END $tests$;
ROLLBACK;
